const DirectCore={
 radius(value,min=88,max=440){let r=Math.max(min,Math.min(max,Number(value)||130));for(const n of [104,130,176])if(Math.abs(r-n)<=4)r=n;return Math.round(r)},
 readerSpot(project,projects){const p=project.space,w=360,h=320,gap=36,candidates=[{x:p.x+p.r+gap,y:p.y-p.r},{x:p.x-p.r-gap-w,y:p.y-p.r},{x:p.x-w/2,y:p.y+p.r+gap},{x:p.x-w/2,y:p.y-p.r-gap-h}];const score=b=>projects.filter(x=>x.id!==project.id).reduce((n,x)=>{const cx=Math.max(b.x,Math.min(b.x+w,x.space.x)),cy=Math.max(b.y,Math.min(b.y+h,x.space.y));return n+(Math.hypot(cx-x.space.x,cy-x.space.y)<x.space.r+20?1:0)},0);return candidates.sort((a,b)=>score(a)-score(b))[0]},
 box(box,vw,vh,minW=280,minH=160){const w=Math.max(Math.min(minW,vw-16),Math.min(vw-16,+box.w||minW)),h=Math.max(Math.min(minH,vh-16),Math.min(vh-16,+box.h||minH));return{x:Math.max(8,Math.min(vw-w-8,+box.x||8)),y:Math.max(8,Math.min(vh-h-8,+box.y||8)),w,h}},
 changedProjects(before,after){const ids=new Set([...before.projects,...after.projects].map(p=>p.id));return [...ids].filter(id=>{const a=before.projects.find(p=>p.id===id),b=after.projects.find(p=>p.id===id);return !a||!b||a.boardId!==b.boardId||[a.coordinator,...a.members].some(m=>![b.coordinator,...b.members].some(n=>n.id===m.id))})},
 endpoints(state,ref){if(ref.startsWith('cluster:'))return (state.clusters||[]).find(c=>c.id===ref.slice(8))?.projectIds.filter(id=>state.projects.some(p=>p.id===id))||[];return state.projects.some(p=>p.id===ref)?[ref]:[]},
 pairs(state,src,dst){const a=this.endpoints(state,src),b=this.endpoints(state,dst);if(!a.length||!b.length||src===dst)throw new Error('请选择不同的有效项目或项目组');const pairs=a.flatMap(x=>b.filter(y=>y!==x).map(y=>[x,y]));if(!pairs.length)throw new Error('项目组之间没有可连接的不同项目');if(pairs.length>64)throw new Error('连接涉及过多项目，请拆分项目组');return pairs},
 bounds(projects,pad=58){if(!projects.length)return{x:0,y:0,r:240};const left=Math.min(...projects.map(p=>p.space.x-p.space.r)),right=Math.max(...projects.map(p=>p.space.x+p.space.r)),top=Math.min(...projects.map(p=>p.space.y-p.space.r)),bottom=Math.max(...projects.map(p=>p.space.y+p.space.r)),x=(left+right)/2,y=(top+bottom)/2;return{x,y,r:Math.ceil(Math.max(...projects.map(p=>Math.hypot(p.space.x-x,p.space.y-y)+p.space.r))+pad)}},
 affectedRuns(runs,ids){return runs.filter(r=>['running','paused','blocked','interrupted','failed'].includes(r.status)&&r.projects.some(p=>ids.includes(p.data.id)))},
 linkPatches(before,after,edges){const pick=l=>l?{name:l.name,state:l.state,trigger:l.trigger,keyword:l.keyword||'',share:l.share}:null;return edges.flatMap(e=>{const a=pick(before.find(l=>l.id===e.id)),b=pick(after.find(l=>l.id===e.id));if(JSON.stringify(a)===JSON.stringify(b))return[];return[{linkId:e.id,patch:b||{state:'disconnected'}}]})},
 arrow(card,target,vw,vh){const tx=target.x+target.w/2,ty=target.y+target.h/2,cx=card.x+card.w/2,cy=card.y+card.h/2,dx=tx-cx,dy=ty-cy,k=1/Math.max(Math.abs(dx)/(card.w/2+12),Math.abs(dy)/(card.h/2+12),1);return{sx:cx+dx*k,sy:cy+dy*k,tx:Math.max(8,Math.min(vw-8,tx)),ty:Math.max(8,Math.min(vh-8,ty))}}
};
