const DM={drag:null,busy:false,restoring:false,readerScroll:new Map(),readerRequested:new Set(),linkFrom:null,toastTimer:null,linkSync:Promise.resolve()};
state.clusters=state.clusters||[];state.bundleLinks=state.bundleLinks||[];state.readers=state.readers||[];state.prefs.windowBoxes=state.prefs.windowBoxes||{};
