function dmToast(text){let el=$('#dm-toast');if(!el){el=document.createElement('div');el.id='dm-toast';el.setAttribute('role','status');document.body.append(el)}el.innerHTML=`<span>${esc(text)}</span><button data-act="undo" aria-label="恢复上一步">${icon('undo',14)}恢复</button><button data-dm-dismiss aria-label="关闭提示">×</button>`;el.hidden=false;clearTimeout(DM.toastTimer);DM.toastTimer=setTimeout(()=>el.hidden=true,8000)}
function dmUiState(){return{panK,panId,guide:$('#guide').classList.contains('o'),utility:utility.classList.contains('o')?utilityKind:null,models:modelConnect.open?{tab:MC.tab,pid:MC.pid,mid:MC.mid}:null,library:skillbook.open?{pid:SB.projectId}:null,tutorialHome:tutorialHome.open}}
