function dmSyncRestoredLinks(before){if(cpPractice())return;for(const r of CP.runs.values()){if(r.status==='completed'||r.boardId!==state.activeBoard)continue;for(const change of DirectCore.linkPatches(before,state.links,r.edges)){const payload=JSON.parse(JSON.stringify({id:r.id,...change}));DM.linkSync=DM.linkSync.then(()=>cpApi('link',payload)).then(cpApply).catch(e=>hint('连接恢复未确认：'+(e.message||String(e))))}}}
const dmRestoreBase=restore;restore=function(str){const before=JSON.parse(JSON.stringify(state.links));DM.restoring=true;try{dmRestoreBase(str);state.clusters=state.clusters||[];state.bundleLinks=state.bundleLinks||[];state.readers=state.readers||[];state.prefs.windowBoxes=state.prefs.windowBoxes||{};const ui=state.interfaceState;if(ui){if(ui.panK)openPan(ui.panK,ui.panId);else closePan();$('#guide').classList.toggle('o',!!ui.guide);if(ui.guide)renderGuide();if(ui.utility)openUtility(ui.utility);else utility.classList.remove('o');if(ui.models)void mcOpen(ui.models.tab,ui.models.pid,ui.models.mid);else if(modelConnect.open)mcClose();if(ui.library)sbOpen(ui.library.pid);else if(skillbook.open)skillbook.close();if(ui.tutorialHome)tutorialOpenHome();else if(tutorialHome.open)tutorialHome.close()}dmSyncRestoredLinks(before);dmDecorate()}finally{DM.restoring=false}};
function dmMutation(name,args,fn,ids=[]){if(DM.busy)throw'上一步正在保存，请稍候';let affected=cpPractice()?[]:DirectCore.affectedRuns([...CP.runs.values()],ids);if(name==='member.remove')affected=affected.filter(r=>r.projects.some(p=>p.data.id===args.projectId&&[p.data.coordinator,...p.data.members].some(m=>m?.id===args.memberId)));if(args.targetState)affected=affected.filter(r=>r.projects.some(p=>{const targetProject=args.targetState.projects.find(x=>x.id===p.data.id);return !targetProject||targetProject.boardId!==r.boardId||[p.data.coordinator,...p.data.members].some(m=>![targetProject.coordinator,...targetProject.members].some(x=>x.id===m.id))}));const turns=[...(typeof liveTurns==='undefined'?[]:liveTurns),...(typeof pendingTurns==='undefined'?[]:pendingTurns)].filter(([mid,t])=>ids.includes(t.pid)&&(name!=='member.remove'||mid===args.memberId)&&(!args.targetState||!args.targetState.projects.some(p=>p.id===t.pid&&[p.coordinator,...p.members].some(m=>m.id===mid))));if(!affected.length&&!turns.length){const result=fn();dmToast(result||'已更新，可撤销');return result}DM.busy=true;void(async()=>{try{for(const [,t] of turns)t.ac.abort();for(const r of affected)cpApply(await cpApi('stop',{id:r.id}));if(turns.length){const end=Date.now()+4000;while(turns.some(([mid,t])=>liveTurns.get(mid)===t||pendingTurns.get(mid)===t)){if(Date.now()>end)throw new Error('请求正在结束，请稍后重试此操作');await new Promise(resolve=>setTimeout(resolve,20))}}const result=fn();renderAll();dmToast((result||'已更新')+'；原流程已停止，成果保留')}catch(e){hint('操作未完成：'+(e.message||String(e)))}finally{DM.busy=false}})();return'正在保存已有成果并更新对象';}
for(const name of ['project.delete','member.remove']){const old=ACT[name];ACT[name]=a=>{const p=rp(a.projectId);if(name==='member.remove'&&mem(p,a.memberId)===p.coordinator)throw'可先把其他成员设为统筹，再移除此成员';return dmMutation(name,a,()=>{if(target===a.memberId)target=null;const result=old({...a,confirm:true});if(name==='project.delete')dmRebuildBundles();return result},[p.id])};}
for(const name of ['undo','redo']){const old=ACT[name];ACT[name]=a=>{const stack=name==='undo'?undoS:redoS;if(!stack.length)return old(a);const targetState=JSON.parse(stack.at(-1));return dmMutation(name,{...a,targetState},()=>old(a),DirectCore.changedProjects(state,targetState))};}
for(const name of ['note.delete','file.delete','link.delete']){const old=ACT[name];ACT[name]=a=>{const result=old({...a,confirm:true});dmToast(result);return result};}
for(const name of ['project.delete','member.remove','note.delete','file.delete','link.delete']){const item=CAT.find(c=>c[0]===name);if(item)item[1]=item[1].replace('需确认','可撤销')}
const dmMoveBase=ACT['project.move'];ACT['project.move']=a=>{const p=rp(a.projectId),cross=a.boardId&&a.boardId!==p.boardId;if(cross)fnd(state.boards,a.boardId,'画板');return dmMutation('project.move',a,()=>{const result=dmMoveBase({...a,confirm:true});if(cross){for(const c of state.clusters)c.projectIds=c.projectIds.filter(id=>P(id)?.boardId===c.boardId);for(const r of state.readers){const f=state.files.find(f=>f.id===r.fileId);if(f)r.boardId=f.boardId}dmRebuildBundles();save()}return result},cross?[p.id]:[])};
CAT.push(['project.resize','调整项目选区大小','projectId,r'],['board.delete','删除画板（本地可撤销）','boardId'],['reader.open','在画板展开文件正文阅读框','fileId'],['reader.close','收回文件阅读框','fileId'],['team.open','在聊天中增减和调整成员','projectId'],['cluster.create','建立容纳多个子项目的选区组','name?,projectIds?'],['cluster.open','管理项目组大圈','clusterId'],['cluster.delete','解散项目组并保留子项目','clusterId'],['bundle.create','连接项目或整个项目组','src,dst']);
ACT['project.resize']=a=>{const p=rp(a.projectId);pushUndo();p.space.r=DirectCore.radius(a.r);save();return'已调整选区大小，可撤销'};
ACT['board.delete']=a=>{const b=fnd(state.boards,a.boardId,'画板');return dmMutation('board.delete',a,()=>{pushUndo();const ids=state.projects.filter(p=>p.boardId===b.id).map(p=>p.id);state.boards=state.boards.filter(x=>x!==b);state.projects=state.projects.filter(p=>p.boardId!==b.id);state.notes=state.notes.filter(n=>n.boardId!==b.id);state.files=state.files.filter(f=>f.boardId!==b.id);state.links=state.links.filter(l=>!ids.includes(l.src)&&!ids.includes(l.dst));state.clusters=state.clusters.filter(c=>c.boardId!==b.id);state.bundleLinks=state.bundleLinks.filter(c=>c.boardId!==b.id);state.readers=state.readers.filter(c=>c.boardId!==b.id);if(!state.boards.length)state.boards.push({id:'b'+uid(),name:'新画板',view:{x:0,y:0,k:1}});if(state.activeBoard===b.id){state.activeBoard=state.boards[0].id;state.room=null;state.sel=null}syncGroups();closePan();save();return'已删除画板，可撤销'},state.projects.filter(p=>p.boardId===b.id).map(p=>p.id))};
ACT['team.open']=a=>{openPan('team',rp(a.projectId).id);return'已打开成员，可直接增减'};
ACT['reader.open']=a=>{const f=fnd(state.files,a.fileId,'文件');let r=state.readers.find(r=>r.fileId===f.id);pushUndo();if(!r){const p=P(f.pid);r={id:'reader'+uid(),fileId:f.id,boardId:f.boardId,...(p?DirectCore.readerSpot(p,onB(state.projects)): {x:f.x+100,y:f.y}),w:360,h:320};state.readers.push(r)}r.boardId=f.boardId;r.open=true;r.collapsed=false;save();const project=P(f.pid);if(project)fit([project,{space:{x:r.x+r.w/2,y:r.y+r.h/2,r:Math.hypot(r.w,r.h)/2}}]);renderBoard();void dmRead(f);return'已展开正文，可拖动、缩放或收回'};
ACT['reader.close']=a=>{const r=state.readers.find(r=>r.fileId===a.fileId);if(r){pushUndo();r.open=false;save();renderBoard();dmToast('阅读框已收回，可恢复')}return'已收回阅读框'};
ACT['cluster.create']=a=>{let ids=Array.isArray(a.projectIds)?a.projectIds:typeof a.projectIds==='string'?a.projectIds.split(','):onB(state.projects).map(p=>p.id);ids=[...new Set(ids)].filter(id=>P(id)?.boardId===state.activeBoard);if(ids.length<2)throw'请先建立至少两个子项目';if(state.clusters.some(c=>c.projectIds.some(id=>ids.includes(id))))throw'所选子项目已有归属，请先从原项目组移出';pushUndo();const c={id:'cluster'+uid(),boardId:state.activeBoard,name:a.name||'项目组',projectIds:ids,...DirectCore.bounds(ids.map(P))};state.clusters.push(c);save();openPan('cluster',c.id);return'已建立大圈项目组'};
ACT['cluster.open']=a=>{openPan('cluster',fnd(state.clusters,a.clusterId,'项目组').id);return'已打开项目组'};
ACT['cluster.delete']=a=>{const c=fnd(state.clusters,a.clusterId,'项目组');return dmMutation('cluster.delete',a,()=>{pushUndo();const bundles=state.bundleLinks.filter(b=>b.src==='cluster:'+c.id||b.dst==='cluster:'+c.id),ids=bundles.flatMap(b=>b.edgeIds);state.links=state.links.filter(l=>!ids.includes(l.id));state.bundleLinks=state.bundleLinks.filter(b=>!bundles.includes(b));state.clusters=state.clusters.filter(x=>x!==c);syncGroups();closePan();save();return'已解散项目组，子项目保留，可撤销'},c.projectIds)};
ACT['bundle.create']=a=>{if(!a.src.startsWith('cluster:')&&!a.dst.startsWith('cluster:'))return ACT['link.create'](a);const pairs=DirectCore.pairs(state,a.src,a.dst);if(pairs.some(([x,y])=>P(x).boardId!==P(y).boardId))throw'请在同一画板内连接';if(pairs.some(([x,y])=>state.links.some(l=>l.src===x&&l.dst===y)))throw'部分子项目已有同方向连接，可先管理或断开原连接';pushUndo();const b={id:'bundle'+uid(),boardId:state.activeBoard,src:a.src,dst:a.dst,name:dmName(a.src)+' → '+dmName(a.dst),edgeIds:[]};for(const [src,dst] of pairs){const l={id:'l'+uid(),src,dst,name:b.name,state:'draft',trigger:'manual',keyword:'',share:{summary:true,artifacts:true,documents:false,noteIds:[]},bundleId:b.id};state.links.push(l);b.edgeIds.push(l.id)}state.bundleLinks.push(b);syncGroups();save();openPan('bundle',b.id);return'已连接整个项目组，选定共享内容并启用后才交付'};
function dmTeamMarkup(p){return `<h3>团队成员<button class="x" data-close="pan" aria-label="关闭">${icon('close')}</button></h3><p class="lab">新增成员应用于下一次任务；模型绑定后才会真实调用。</p><div class="dm-model-picks">${Object.entries(MODELS).map(([id,m])=>B_('member.add',{projectId:p.id,agent:id},m[0],'plus')).join('')}</div>${[p.coordinator,...p.members].map(m=>`<div class="dm-member">${piece(m.agent,30,m===p.coordinator)}<div><input data-mn="${p.id}|${m.id}" aria-label="成员名称" value="${esc(m.name)}"><input data-mr="${p.id}|${m.id}" aria-label="成员职责" value="${esc(m.role)}"><small>${esc(m.model||'尚未绑定模型')}</small></div><div>${B_('models.handoff',{projectId:p.id,memberId:m.id},'模型')}${m===p.coordinator?'<span class="lab">统筹</span>':`<button data-dm-lead="${p.id}|${m.id}">设为统筹</button>${B_('member.remove',{projectId:p.id,memberId:m.id},'移除','trash')}`}</div></div>`).join('')}`}
function dmClusterMarkup(c){return `<h3>项目组 · ${esc(c.name)}<button class="x" data-close="pan" aria-label="关闭">${icon('close')}</button></h3><label>名称<input data-dm-cluster-name="${c.id}" value="${esc(c.name)}"></label><p class="lab">组内为独立子项目。拖项目组标题整体移动，拖右下手柄调整范围。</p>${c.projectIds.map(id=>P(id)).filter(Boolean).map(p=>`<div class="row">${esc(p.name)}<button data-dm-cluster-out="${c.id}|${p.id}">移出组</button></div>`).join('')}<div class="row"><select id="dm-cluster-add"><option value="">加入子项目</option>${onB(state.projects).filter(p=>!state.clusters.some(c=>c.projectIds.includes(p.id))).map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select><button data-dm-cluster-add="${c.id}">加入</button></div>${dmConnectMarkup('cluster:'+c.id)}<div class="row">${B_('cluster.delete',{clusterId:c.id},'解散项目组，保留子项目','trash')}</div>`}
function dmConnectMarkup(src){return `<div class="lab">连接项目 / 整个项目组</div><div class="row"><select data-dm-destination="${src}">${[...onB(state.projects).map(p=>({id:p.id,name:p.name})),...dmClusters().map(c=>({id:'cluster:'+c.id,name:'项目组 · '+c.name}))].filter(p=>p.id!==src).map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select><button data-dm-connect="${src}">连接</button></div>`}
function dmBundleMarkup(b){const l=state.links.find(l=>b.edgeIds.includes(l.id));if(!l)return`<h3>${esc(b.name)}<button class="x" data-close="pan" aria-label="关闭">×</button></h3><p>项目组暂无有效路径，可加入子项目或断开此连接。</p><button data-dm-bundle-delete="${b.id}">断开</button>`;return `<h3>${esc(b.name)}<button class="x" data-close="pan" aria-label="关闭">${icon('close')}</button></h3><p class="lab">${b.edgeIds.length} 条子项目路径 · ${LS[l.state]}</p><label>触发<select data-dm-bundle-trigger="${b.id}">${Object.entries(TRIG).map(([k,v])=>`<option value="${k}" ${l.trigger===k?'selected':''}>${v}</option>`).join('')}</select></label><label>关键词（可选）<input data-dm-bundle-keyword="${b.id}" value="${esc(l.keyword||'')}"></label>${[['summary','目标摘要'],['artifacts','已完成产物'],['documents','已读取文件正文']].map(([k,n])=>`<label class="row"><input type="checkbox" data-dm-bundle-share="${b.id}|${k}" ${l.share[k]?'checked':''}>${n}</label>`).join('')}<p class="lab">仅共享勾选内容。连线配置不会自动开始模型请求。</p><div class="row"><button data-dm-bundle-state="${b.id}|${l.state==='on'?'paused':'on'}">${l.state==='on'?'暂停':l.state==='paused'?'恢复':'启用'}</button><button data-dm-bundle-delete="${b.id}">断开</button></div>`}
const dmPanBase=renderPan;renderPan=function(){if(panK==='team'){const p=P(panId);if(!p)return closePan();$('#pan').innerHTML=dmTeamMarkup(p)}else if(panK==='cluster'){const c=dmCluster(panId);if(!c)return closePan();$('#pan').innerHTML=dmClusterMarkup(c)}else if(panK==='bundle'){const b=state.bundleLinks.find(x=>x.id===panId);if(!b)return closePan();$('#pan').innerHTML=dmBundleMarkup(b)}else{dmPanBase();if(panK==='proj'){const p=P(panId);if(p)$('#pan').insertAdjacentHTML('beforeend',`<div class="lab">选区大小</div><input type="range" min="88" max="440" value="${p.space.r}" aria-label="项目选区大小" data-dm-radius="${p.id}">${B_('team.open',{projectId:p.id},'增减团队成员','users')}${dmConnectMarkup(p.id)}`)}if(panK==='boards')for(const b of state.boards){const row=[...$('#pan').querySelectorAll('.row')].find(row=>row.querySelector('[data-brn]')?.dataset.brn===b.id);row?.insertAdjacentHTML('beforeend',B_('board.delete',{boardId:b.id},'删除','trash'))}if(panK==='file')$('#pan #pv')?.insertAdjacentHTML('beforebegin',B_('reader.open',{fileId:panId},'展开关联阅读框','file'))}dmDecorate()};
