async function dmRead(f){if(DF.reading.has(f.id))return;if(B()?.tutorialSessionId){const blob=await idb('get',f.id).catch(()=>null);if(blob&&/\.(md|txt|csv|json|log)$/i.test(f.name)){DF.records.set(f.id,{status:'ready',segments:[{location:'本地练习文本',text:await blob.text()}],warnings:['本地演练，不调用模型']});dmUpdateReaders()}return}try{const ac=new AbortController();DF.reading.set(f.id,ac);await dfRead(f,ac.signal)}catch(e){DF.error=e.message}finally{DF.reading.delete(f.id);dmUpdateReaders()}}
