function dmRebuildBundles(){for(const c of state.clusters)c.projectIds=c.projectIds.filter(id=>P(id));for(const b of state.bundleLinks.slice()){const old=state.links.filter(l=>b.edgeIds.includes(l.id)),sample=old[0]||b.settings||{state:'draft',trigger:'manual',keyword:'',share:{summary:true,artifacts:true,documents:false,noteIds:[]}};let pairs;try{pairs=DirectCore.pairs(state,b.src,b.dst)}catch{pairs=[]}const keep=[];for(const [src,dst] of pairs){let edge=old.find(l=>l.src===src&&l.dst===dst);if(!edge){if(state.links.some(l=>l.src===src&&l.dst===dst&&l.bundleId!==b.id))continue;edge={...sample,id:'l'+uid(),src,dst,bundleId:b.id,share:structuredClone(sample.share)};state.links.push(edge)}keep.push(edge.id)}const removed=b.edgeIds.filter(id=>!keep.includes(id));state.links=state.links.filter(l=>!removed.includes(l.id));b.edgeIds=keep;for(const r of CP.runs.values())for(const id of removed)if(r.status!=='completed'&&r.edges.some(e=>e.id===id))void cpApi('link',{id:r.id,linkId:id,patch:{state:'disconnected'}}).then(cpApply).catch(e=>hint(e.message));if(!keep.length&&!DirectCore.endpoints(state,b.src).length)state.bundleLinks=state.bundleLinks.filter(x=>x!==b)}syncGroups()}
